actions.script:
const recordOut = ec.service.sync().name('ironstone.ChatterServices.get#RecordInfo').parameters({recordEntityName: recordEntity || '',
    recordId: recordId || ''}).call()
if (!recordOut.visible) { ec.web.sendJsonResponse({visible: false}); return }
const out = ec.service.sync().name('ironstone.RecordFilesServices.get#RecordFiles').parameters({recordEntityName: recordEntity,
    recordId: recordId}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {visible: true, record: {title: recordOut.title, typeLabel: recordOut.typeLabel},
    hasContent: out.hasContent, canUpload: out.canUpload, fileList: out.fileList, fileCount: out.fileCount, typeOptions: out.typeOptions,
    defaultTypeId: out.defaultTypeId, recordsDriveId: out.recordsDriveId, recordFolderPath: out.recordFolderPath, filesUrl: out.filesUrl,
    extraList: out.extraList})

const out = ec.service.sync().name('ironstone.RecordFilesServices.upload#RecordFile').parameters({recordEntityName: recordEntity,
    recordId: recordId, contentFile: contentFile || null, contentTypeEnumId: contentTypeEnumId || null, description: description || null}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const infos = [{type: 'success', message: out.message}]
for (const failed of Array.from(out.failedList || [])) infos.push({type: 'warning', message: failed.fileName + ': ' + failed.error})
ec.web.sendJsonResponse({createdList: out.createdList, failedList: out.failedList, messageInfos: infos})

const out = ec.service.sync().name('ironstone.RecordFilesServices.remove#RecordFile').parameters({recordEntityName: recordEntity,
    recordId: recordId, contentKey: contentKey}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.RecordFilesServices.get#RecordFileVersions').parameters({recordEntityName: recordEntity || '',
    recordId: recordId || '', drivePath: drivePath || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {versionList: out.versionList, canChange: out.canChange})

const out = ec.service.sync().name('ironstone.RecordFilesServices.get#RecordDriveFile').parameters({recordEntityName: recordEntity || '',
    recordId: recordId || '', drivePath: drivePath || '', versionName: versionName || null}).call()
if (ec.message.hasError() || !out.location) ec.web.sendJsonResponse({})
else ec.web.sendResourceResponse(out.location, String(inline) === 'true' && out.inlineAllowed, out.fileName)

const out = ec.service.sync().name('ironstone.RecordFilesServices.upload#RecordFileVersion').parameters({recordEntityName: recordEntity,
    recordId: recordId, drivePath: drivePath || '', contentFile: contentFile || null, versionNote: versionNote || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {versionName: out.versionName, messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.RecordFilesServices.restore#RecordFileVersion').parameters({recordEntityName: recordEntity,
    recordId: recordId, drivePath: drivePath || '', versionName: versionName || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: out.message}]})

let items = []
try { items = JSON.parse(itemsJson || '[]') } catch (err) { items = [] }
const out = ec.service.sync().name('ironstone.RecordFilesServices.add#RecordFilesFromDrive').parameters({recordEntityName: recordEntity,
    recordId: recordId, itemList: items, contentTypeEnumId: contentTypeEnumId || null, description: description || null}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const infos = [{type: 'success', message: out.message}]
for (const failed of Array.from(out.failedList || [])) infos.push({type: 'warning', message: failed.fileName + ': ' + failed.error})
ec.web.sendJsonResponse({createdList: out.createdList, failedList: out.failedList, messageInfos: infos})

const out = ec.service.sync().name('ironstone.RecordFilesServices.get#RecordFile').parameters({recordEntityName: recordEntity || '',
    recordId: recordId || '', contentKey: contentKey || ''}).call()
if (!ec.message.hasError() && !out.contentLocation) ec.message.addError(ec.l10n.localize('This file has no content'))
if (ec.message.hasError()) ec.web.sendJsonResponse({})
else ec.web.sendResourceResponse(out.contentLocation, String(inline) === 'true' && out.inlineAllowed, out.fileName || null)
